SELECT * FROM (
SELECT p.arxiv_id, p.title, p.published, p.primary_category, pc.is_primary FROM papers p JOIN paper_categories pc ON p.arxiv_id = pc.arxiv_id WHERE pc.category = 'cs.MA' AND p.published LIKE '2025%' ORDER BY p.published DESC
) LIMIT 51

SELECT * FROM (
SELECT p.arxiv_id, p.title, p.published, p.year, pc.category FROM papers p JOIN paper_categories pc ON p.arxiv_id = pc.arxiv_id WHERE pc.category = 'cs.MA' ORDER BY p.published DESC
) LIMIT 51
